insert into kafaa_skill_change_requests (id, kind, skill_id, title_en, title_ar, proposal, rationale, development, assessment, inclusion, status, proposed_by, proposed_role, proposed_at, votes, first_by, first_decision, second_by, decided_at, change_id, updated_at) values
('scr-029', 'add', null, 'Add "Plant-data quality"', 'إضافة «جودة بيانات المحطة»', '{"name_en":"Plant-data quality","name_ar":"جودة بيانات المحطة","description_en":"Spots drift, gaps and bad tags in plant historian data, records where each data set came from and keeps data fit for safety analysis. Part of System health monitoring (EN-02).","description_ar":"يكتشف الانحراف والفجوات والوسوم الخاطئة في البيانات التاريخية للمحطة، ويسجّل مصدر كل مجموعة بيانات، ويحافظ على صلاحيتها لتحليلات السلامة. جزء من رصد سلامة الأنظمة (EN-02).","area":"engineering","competency_id":"en-02","fs_area":"ai_data","key_level":2,"decay_class":"fast","owner_role":"engineering","source_label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","source_url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}'::jsonb, 'AI tools are in daily use under the AI register; the skills to use, verify and govern them must be evidenced separately.', 'Developed through the future-skills course pack, the governed AI sandbox drills and AI fluency rungs.', 'Assessed with the adaptive AI-literacy bank, performance tasks or drills, each mapped to this skill only.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-sme-reviewer', 'employee', '2026-07-28T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-08-04T10:00:00Z"},{"by":"p-k-admin","role":"admin","decision":"approve","note":null,"at":"2026-08-11T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-k-admin', '2026-08-11T11:00:00Z', 'sc-029', '2026-08-11T11:00:00Z'),
('scr-030', 'add', null, 'Add "Automation design"', 'إضافة «تصميم الأتمتة»', '{"name_en":"Automation design","name_ar":"تصميم الأتمتة","description_en":"Designs small automations for administrative workflows with a named owner, a fallback and a test record, never for plant control. Part of Digital tools and data literacy (DA-01).","description_ar":"يصمّم أتمتة صغيرة لسير العمل الإداري مع مالك محدد وخطة بديلة وسجل اختبار، ولا يستخدمها أبداً في التحكم بالمحطة. جزء من الأدوات الرقمية ومحو الأمية في البيانات (DA-01).","area":"digital","competency_id":"da-01","fs_area":"ai_data","key_level":2,"decay_class":"fast","owner_role":"digital_ai_governance","source_label":"ADNOC AI upskilling and EGA Academy","source_url":"https://reports.adnoc.ae/e/sustainability-report-2025/eJFjvFKd42"}'::jsonb, 'AI tools are in daily use under the AI register; the skills to use, verify and govern them must be evidenced separately.', 'Developed through the future-skills course pack, the governed AI sandbox drills and AI fluency rungs.', 'Assessed with the adaptive AI-literacy bank, performance tasks or drills, each mapped to this skill only.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-sme-reviewer', 'employee', '2026-07-28T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-08-04T10:00:00Z"},{"by":"p-k-admin","role":"admin","decision":"approve","note":null,"at":"2026-08-11T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-k-admin', '2026-08-11T11:00:00Z', 'sc-030', '2026-08-11T11:00:00Z'),
('scr-031', 'add', null, 'Add "AR and VR for training and work"', 'إضافة «الواقع المعزّز والافتراضي في التدريب والعمل»', '{"name_en":"AR and VR for training and work","name_ar":"الواقع المعزّز والافتراضي في التدريب والعمل","description_en":"Uses augmented and virtual reality for walk-downs and practice, and knows where a simulator or the real plant is still required. Part of Digital tools and data literacy (DA-01).","description_ar":"يستخدم الواقع المعزّز والافتراضي في الجولات التفقدية والتدريب، ويعرف متى يظل المحاكي أو المحطة الفعلية ضرورياً. جزء من الأدوات الرقمية ومحو الأمية في البيانات (DA-01).","area":"digital","competency_id":"da-01","fs_area":"ai_data","key_level":2,"decay_class":"fast","owner_role":"nuclear_training","source_label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","source_url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}'::jsonb, 'AI tools are in daily use under the AI register; the skills to use, verify and govern them must be evidenced separately.', 'Developed through the future-skills course pack, the governed AI sandbox drills and AI fluency rungs.', 'Assessed with the adaptive AI-literacy bank, performance tasks or drills, each mapped to this skill only.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-sme-reviewer', 'employee', '2026-07-28T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-08-04T10:00:00Z"},{"by":"p-k-admin","role":"admin","decision":"approve","note":null,"at":"2026-08-11T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-k-admin', '2026-08-11T11:00:00Z', 'sc-031', '2026-08-11T11:00:00Z'),
('scr-032', 'add', null, 'Add "Digital twin validation"', 'إضافة «التحقق من صحة التوائم الرقمية»', '{"name_en":"Digital twin validation","name_ar":"التحقق من صحة التوائم الرقمية","description_en":"Compares twin predictions with plant behaviour, records where the model is valid and flags when it drifts out of its range. Part of Digital tools and data literacy (DA-01).","description_ar":"يقارن تنبؤات التوأم الرقمي بسلوك المحطة، ويسجّل النطاق الذي يصحّ فيه النموذج، وينبّه عند خروجه عن نطاقه. جزء من الأدوات الرقمية ومحو الأمية في البيانات (DA-01).","area":"digital","competency_id":"da-01","fs_area":"ai_data","key_level":3,"decay_class":"fast","owner_role":"engineering","source_label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","source_url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}'::jsonb, 'AI tools are in daily use under the AI register; the skills to use, verify and govern them must be evidenced separately.', 'Developed through the future-skills course pack, the governed AI sandbox drills and AI fluency rungs.', 'Assessed with the adaptive AI-literacy bank, performance tasks or drills, each mapped to this skill only.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-sme-reviewer', 'employee', '2026-07-28T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-08-04T10:00:00Z"},{"by":"p-k-admin","role":"admin","decision":"approve","note":null,"at":"2026-08-11T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-k-admin', '2026-08-11T11:00:00Z', 'sc-032', '2026-08-11T11:00:00Z'),
('scr-033', 'add', null, 'Add "Anomaly triage with AI alerts"', 'إضافة «فرز الحالات الشاذة باستخدام تنبيهات الذكاء الاصطناعي»', '{"name_en":"Anomaly triage with AI alerts","name_ar":"فرز الحالات الشاذة باستخدام تنبيهات الذكاء الاصطناعي","description_en":"Sorts AI-generated anomaly alerts into act, watch and dismiss, with reasons, and feeds the outcome back to the model owner. Part of System health monitoring (EN-02).","description_ar":"يفرز تنبيهات الحالات الشاذة التي يولّدها الذكاء الاصطناعي إلى: تصرّف، أو مراقبة، أو تجاهل، مع الأسباب، ويعيد النتيجة إلى مالك النموذج. جزء من رصد سلامة الأنظمة (EN-02).","area":"engineering","competency_id":"en-02","fs_area":"ai_data","key_level":2,"decay_class":"fast","owner_role":"engineering","source_label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","source_url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}'::jsonb, 'AI tools are in daily use under the AI register; the skills to use, verify and govern them must be evidenced separately.', 'Developed through the future-skills course pack, the governed AI sandbox drills and AI fluency rungs.', 'Assessed with the adaptive AI-literacy bank, performance tasks or drills, each mapped to this skill only.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-sme-reviewer', 'employee', '2026-07-28T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-08-04T10:00:00Z"},{"by":"p-k-admin","role":"admin","decision":"approve","note":null,"at":"2026-08-11T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-k-admin', '2026-08-11T11:00:00Z', 'sc-033', '2026-08-11T11:00:00Z'),
('scr-034', 'add', null, 'Add "Responsible data handling"', 'إضافة «التعامل المسؤول مع البيانات»', '{"name_en":"Responsible data handling","name_ar":"التعامل المسؤول مع البيانات","description_en":"Handles personal and commercial data on a need-to-know basis, minimises what is shared and knows how to report a data mistake. Part of Governed use of AI (DA-02).","description_ar":"يتعامل مع البيانات الشخصية والتجارية على أساس الحاجة إلى المعرفة، ويقلّل ما يُشارك، ويعرف كيف يبلّغ عن خطأ في البيانات. جزء من الاستخدام المحوكم للذكاء الاصطناعي (DA-02).","area":"digital","competency_id":"da-02","fs_area":"ai_data","key_level":2,"decay_class":"fast","owner_role":"digital_ai_governance","source_label":"EU AI Act Article 4 AI-literacy repository and UNESCO AI Competency Frameworks","source_url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices"}'::jsonb, 'AI tools are in daily use under the AI register; the skills to use, verify and govern them must be evidenced separately.', 'Developed through the future-skills course pack, the governed AI sandbox drills and AI fluency rungs.', 'Assessed with the adaptive AI-literacy bank, performance tasks or drills, each mapped to this skill only.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-sme-reviewer', 'employee', '2026-07-28T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-08-04T10:00:00Z"},{"by":"p-k-admin","role":"admin","decision":"approve","note":null,"at":"2026-08-11T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-k-admin', '2026-08-11T11:00:00Z', 'sc-034', '2026-08-11T11:00:00Z'),
('scr-035', 'add', null, 'Add "Lifecycle carbon assessment"', 'إضافة «تقييم الكربون على امتداد دورة الحياة»', '{"name_en":"Lifecycle carbon assessment","name_ar":"تقييم الكربون على امتداد دورة الحياة","description_en":"Estimates the lifecycle emissions of an energy option or project with a stated method and compares it fairly with alternatives. Part of Configuration management and design control (EN-01).","description_ar":"يقدّر انبعاثات خيار طاقة أو مشروع على امتداد دورة حياته بمنهجية معلنة، ويقارنه بالبدائل مقارنة منصفة. جزء من إدارة التهيئة وضبط التصميم (EN-01).","area":"engineering","competency_id":"en-01","fs_area":"green_energy","key_level":2,"decay_class":"standard","owner_role":"sustainability","source_label":"GreenComp, with EntreComp and LifeComp","source_url":"https://joint-research-centre.ec.europa.eu/greencomp"}'::jsonb, 'CleanEnergyComp and the energy-transition pathways need sustainability skills that can be developed and assessed on their own.', 'Developed through the CleanEnergyComp modules and the energy-system pathway, separate from plant chemistry.', 'Assessed through the module assessments and an applied exercise on a sourced value chain.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-08-11T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-08-18T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-08-25T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-08-25T11:00:00Z', 'sc-035', '2026-08-25T11:00:00Z'),
('scr-036', 'add', null, 'Add "GHG accounting basics"', 'إضافة «أساسيات محاسبة غازات الاحتباس الحراري»', '{"name_en":"GHG accounting basics","name_ar":"أساسيات محاسبة غازات الاحتباس الحراري","description_en":"Explains scope 1, 2 and 3 emissions, follows the GHG Protocol logic and checks the data behind a sustainability figure. Part of System health monitoring (EN-02).","description_ar":"يشرح انبعاثات النطاقات 1 و2 و3، ويتبع منطق بروتوكول غازات الاحتباس الحراري، ويتحقق من البيانات وراء أي رقم للاستدامة. جزء من رصد سلامة الأنظمة (EN-02).","area":"engineering","competency_id":"en-02","fs_area":"green_energy","key_level":2,"decay_class":"standard","owner_role":"sustainability","source_label":"GreenComp, with EntreComp and LifeComp","source_url":"https://joint-research-centre.ec.europa.eu/greencomp"}'::jsonb, 'CleanEnergyComp and the energy-transition pathways need sustainability skills that can be developed and assessed on their own.', 'Developed through the CleanEnergyComp modules and the energy-system pathway, separate from plant chemistry.', 'Assessed through the module assessments and an applied exercise on a sourced value chain.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-08-11T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-08-18T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-08-25T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-08-25T11:00:00Z', 'sc-036', '2026-08-25T11:00:00Z'),
('scr-037', 'add', null, 'Add "Hydrogen and process-heat interfaces"', 'إضافة «واجهات الهيدروجين والحرارة الصناعية»', '{"name_en":"Hydrogen and process-heat interfaces","name_ar":"واجهات الهيدروجين والحرارة الصناعية","description_en":"Explains how nuclear heat and power can feed hydrogen and industrial heat users, and the safety and grid questions each interface raises. Part of Thermodynamics, heat transfer and fluid flow (PF-02).","description_ar":"يشرح كيف يمكن للحرارة والكهرباء النوويتين تزويد مستخدمي الهيدروجين والحرارة الصناعية، وأسئلة السلامة والشبكة التي تثيرها كل واجهة. جزء من الديناميكا الحرارية وانتقال الحرارة وجريان الموائع (PF-02).","area":"plant_systems","competency_id":"pf-02","fs_area":"green_energy","key_level":2,"decay_class":"standard","owner_role":"sustainability","source_label":"IEA World Energy Employment 2025 and IRENA/ILO Renewable Energy and Jobs 2025","source_url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025"}'::jsonb, 'CleanEnergyComp and the energy-transition pathways need sustainability skills that can be developed and assessed on their own.', 'Developed through the CleanEnergyComp modules and the energy-system pathway, separate from plant chemistry.', 'Assessed through the module assessments and an applied exercise on a sourced value chain.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-08-11T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-08-18T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-08-25T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-08-25T11:00:00Z', 'sc-037', '2026-08-25T11:00:00Z'),
('scr-038', 'add', null, 'Add "Grid integration and flexible operation"', 'إضافة «التكامل مع الشبكة والتشغيل المرن»', '{"name_en":"Grid integration and flexible operation","name_ar":"التكامل مع الشبكة والتشغيل المرن","description_en":"Understands how a nuclear fleet works alongside solar, storage and the grid operator, including load-following limits and grid-code duties. Part of APR-1400 integrated plant systems (PF-03).","description_ar":"يفهم كيف يعمل أسطول نووي إلى جانب الطاقة الشمسية والتخزين ومشغّل الشبكة، بما في ذلك حدود متابعة الأحمال والتزامات كود الشبكة. جزء من أنظمة محطة APR-1400 المتكاملة (PF-03).","area":"plant_systems","competency_id":"pf-03","fs_area":"green_energy","key_level":2,"decay_class":"standard","owner_role":"operations","source_label":"IEA World Energy Employment 2025 and IRENA/ILO Renewable Energy and Jobs 2025","source_url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025"}'::jsonb, 'CleanEnergyComp and the energy-transition pathways need sustainability skills that can be developed and assessed on their own.', 'Developed through the CleanEnergyComp modules and the energy-system pathway, separate from plant chemistry.', 'Assessed through the module assessments and an applied exercise on a sourced value chain.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-08-11T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-08-18T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-08-25T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-08-25T11:00:00Z', 'sc-038', '2026-08-25T11:00:00Z'),
('scr-039', 'add', null, 'Add "Circularity and waste stewardship"', 'إضافة «الاقتصاد الدائري والإشراف على النفايات»', '{"name_en":"Circularity and waste stewardship","name_ar":"الاقتصاد الدائري والإشراف على النفايات","description_en":"Applies reduce, reuse and recycle to conventional waste and minimises radioactive waste at source, following the site waste hierarchy. Part of Radiochemistry and effluent monitoring (CH-02).","description_ar":"يطبّق مبادئ التقليل وإعادة الاستخدام والتدوير على النفايات التقليدية، ويقلّل النفايات المشعة من مصدرها وفق هرمية إدارة النفايات المعتمدة. جزء من الكيمياء الإشعاعية ورصد المخلفات (CH-02).","area":"radiation_chemistry","competency_id":"ch-02","fs_area":"green_energy","key_level":2,"decay_class":"standard","owner_role":"sustainability","source_label":"GreenComp, with EntreComp and LifeComp","source_url":"https://joint-research-centre.ec.europa.eu/greencomp"}'::jsonb, 'CleanEnergyComp and the energy-transition pathways need sustainability skills that can be developed and assessed on their own.', 'Developed through the CleanEnergyComp modules and the energy-system pathway, separate from plant chemistry.', 'Assessed through the module assessments and an applied exercise on a sourced value chain.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-08-11T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-08-18T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-08-25T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-08-25T11:00:00Z', 'sc-039', '2026-08-25T11:00:00Z'),
('scr-040', 'add', null, 'Add "ESG disclosure literacy"', 'إضافة «الإلمام بالإفصاح البيئي والاجتماعي والحوكمي»', '{"name_en":"ESG disclosure literacy","name_ar":"الإلمام بالإفصاح البيئي والاجتماعي والحوكمي","description_en":"Reads and checks environmental, social and governance disclosures, knows what an auditable metric needs and where a claim needs evidence. Part of NQA-1 quality assurance requirements (QA-01).","description_ar":"يقرأ الإفصاحات البيئية والاجتماعية والحوكمية ويتحقق منها، ويعرف ما يحتاجه المقياس القابل للتدقيق ومتى يحتاج الادعاء إلى دليل. جزء من متطلبات ضمان الجودة وفق NQA-1 (QA-01).","area":"quality","competency_id":"qa-01","fs_area":"green_energy","key_level":2,"decay_class":"standard","owner_role":"sustainability","source_label":"ISO 30414:2025 human capital reporting","source_url":"https://committee.iso.org/sites/tc260/home/news/content-left-area/news-and-updates/iso-30414-2025-strengthening-hum.html"}'::jsonb, 'CleanEnergyComp and the energy-transition pathways need sustainability skills that can be developed and assessed on their own.', 'Developed through the CleanEnergyComp modules and the energy-system pathway, separate from plant chemistry.', 'Assessed through the module assessments and an applied exercise on a sourced value chain.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-08-11T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-08-18T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-08-25T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-08-25T11:00:00Z', 'sc-040', '2026-08-25T11:00:00Z'),
('scr-041', 'add', null, 'Add "Climate risk awareness"', 'إضافة «الوعي بمخاطر المناخ»', '{"name_en":"Climate risk awareness","name_ar":"الوعي بمخاطر المناخ","description_en":"Recognises how heat, humidity, dust and sea conditions affect plant, people and supply chains, and feeds that into planning. Part of Defence in depth and safety functions (NS-01).","description_ar":"يدرك كيف تؤثر الحرارة والرطوبة والغبار وأحوال البحر في المحطة والأفراد وسلاسل الإمداد، ويُدخل ذلك في التخطيط. جزء من الدفاع في العمق ووظائف السلامة (NS-01).","area":"safety","competency_id":"ns-01","fs_area":"green_energy","key_level":2,"decay_class":"standard","owner_role":"sustainability","source_label":"IEA World Energy Employment 2025 and IRENA/ILO Renewable Energy and Jobs 2025","source_url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025"}'::jsonb, 'CleanEnergyComp and the energy-transition pathways need sustainability skills that can be developed and assessed on their own.', 'Developed through the CleanEnergyComp modules and the energy-system pathway, separate from plant chemistry.', 'Assessed through the module assessments and an applied exercise on a sourced value chain.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-08-11T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-08-18T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-08-25T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-08-25T11:00:00Z', 'sc-041', '2026-08-25T11:00:00Z'),
('scr-042', 'add', null, 'Add "Chatbot prompt writing"', 'إضافة «كتابة الأوامر لروبوتات المحادثة»', '{"name_en":"Chatbot prompt writing","name_ar":"كتابة الأوامر لروبوتات المحادثة","area":"digital","competency_id":"da-02","fs_area":"ai_data","key_level":1,"source_label":"European Commission · EU AI Act Article 4 AI-literacy repository","source_url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices"}'::jsonb, 'Outage planners use chatbots to draft work-order texts and want the skill recognised.', 'A short module on writing prompts for the approved chatbot, with examples from planning work.', 'A practical exercise: draft three prompts and review the outputs with a peer.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'rejected', 'p-outage-planner', 'employee', '2026-09-09T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"reject","note":"Not distinct from Prompt and agent literacy (FS-AI-03): same development and the same assessment.","at":"2026-09-12T10:00:00Z"},{"by":"p-k-admin","role":"admin","decision":"reject","note":"Agree: covered by FS-AI-03; suggest the planner examples are added to its practice set.","at":"2026-09-14T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'reject', 'p-k-admin', '2026-09-14T11:00:00Z', null, '2026-09-14T11:00:00Z'),
('scr-043', 'add', null, 'Add "SMR fundamentals"', 'إضافة «أساسيات المفاعلات المعيارية الصغيرة»', '{"name_en":"SMR fundamentals","name_ar":"أساسيات المفاعلات المعيارية الصغيرة","description_en":"Compares the main SMR and microreactor design families with the APR-1400: size, coolant, fuel and what changes for operations. Part of Reactor theory and nuclear physics fundamentals (PF-01). Awareness only: no deployment decision is implied.","description_ar":"يقارن عائلات تصاميم المفاعلات المعيارية الصغيرة والمفاعلات الدقيقة الرئيسية بمفاعل APR-1400: الحجم والمبرّد والوقود وما يتغير في التشغيل. جزء من نظرية المفاعل وأساسيات الفيزياء النووية (PF-01). للتوعية فقط: لا يعني ذلك أي قرار بالنشر.","area":"plant_systems","competency_id":"pf-01","fs_area":"advanced_reactor","key_level":2,"decay_class":"standard","owner_role":"advanced_reactors","source_label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","source_url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}'::jsonb, 'Awareness of next-generation reactor concepts is needed for the SMR delta and future roles (no deployment decision implied).', 'Developed through the SMR foundations micro-credential and expert lectures; awareness of concepts, no deployment decision implied.', 'Assessed through the micro-credential criteria and a short concept review, separate from current plant systems.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-09-01T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-09-08T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-09-15T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-09-15T11:00:00Z', 'sc-042', '2026-09-15T11:00:00Z'),
('scr-044', 'add', null, 'Add "Passive safety concepts"', 'إضافة «مفاهيم السلامة السلبية»', '{"name_en":"Passive safety concepts","name_ar":"مفاهيم السلامة السلبية","description_en":"Explains how passive systems remove decay heat without pumps or operator action, and what still needs monitoring and human judgement. Part of Defence in depth and safety functions (NS-01). Awareness only: no deployment decision is implied.","description_ar":"يشرح كيف تزيل الأنظمة السلبية الحرارة المتبقية دون مضخات أو تدخل المشغّل، وما الذي يظل بحاجة إلى المراقبة والحكم البشري. جزء من الدفاع في العمق ووظائف السلامة (NS-01). للتوعية فقط: لا يعني ذلك أي قرار بالنشر.","area":"safety","competency_id":"ns-01","fs_area":"advanced_reactor","key_level":2,"decay_class":"standard","owner_role":"advanced_reactors","source_label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","source_url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}'::jsonb, 'Awareness of next-generation reactor concepts is needed for the SMR delta and future roles (no deployment decision implied).', 'Developed through the SMR foundations micro-credential and expert lectures; awareness of concepts, no deployment decision implied.', 'Assessed through the micro-credential criteria and a short concept review, separate from current plant systems.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-09-01T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-09-08T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-09-15T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-09-15T11:00:00Z', 'sc-043', '2026-09-15T11:00:00Z'),
('scr-045', 'add', null, 'Add "Multi-module operations concepts"', 'إضافة «مفاهيم تشغيل الوحدات المتعددة»', '{"name_en":"Multi-module operations concepts","name_ar":"مفاهيم تشغيل الوحدات المتعددة","description_en":"Describes how one crew may supervise several modules, the human-factors questions this raises and how staffing cases are justified. Part of Reactivity management (CO-03). Awareness only: no deployment decision is implied.","description_ar":"يصف كيف يمكن لطاقم واحد الإشراف على عدة وحدات، وأسئلة العوامل البشرية التي يثيرها ذلك، وكيف تُبرَّر حالات تحديد الطواقم. جزء من إدارة التفاعلية (CO-03). للتوعية فقط: لا يعني ذلك أي قرار بالنشر.","area":"operations","competency_id":"co-03","fs_area":"advanced_reactor","key_level":2,"decay_class":"standard","owner_role":"advanced_reactors","source_label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","source_url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}'::jsonb, 'Awareness of next-generation reactor concepts is needed for the SMR delta and future roles (no deployment decision implied).', 'Developed through the SMR foundations micro-credential and expert lectures; awareness of concepts, no deployment decision implied.', 'Assessed through the micro-credential criteria and a short concept review, separate from current plant systems.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-09-01T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-09-08T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-09-15T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-09-15T11:00:00Z', 'sc-044', '2026-09-15T11:00:00Z'),
('scr-046', 'add', null, 'Add "Factory fabrication QA"', 'إضافة «ضمان الجودة في التصنيع بالمصنع»', '{"name_en":"Factory fabrication QA","name_ar":"ضمان الجودة في التصنيع بالمصنع","description_en":"Applies nuclear QA to modules built in a factory: source inspection, traceability and acceptance testing before shipment. Part of NQA-1 quality assurance requirements (QA-01). Awareness only: no deployment decision is implied.","description_ar":"يطبّق ضمان الجودة النووية على الوحدات المصنّعة في المصنع: الفحص عند المصدر، وإمكانية التتبّع، واختبارات القبول قبل الشحن. جزء من متطلبات ضمان الجودة وفق NQA-1 (QA-01). للتوعية فقط: لا يعني ذلك أي قرار بالنشر.","area":"quality","competency_id":"qa-01","fs_area":"advanced_reactor","key_level":2,"decay_class":"standard","owner_role":"quality","source_label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","source_url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}'::jsonb, 'Awareness of next-generation reactor concepts is needed for the SMR delta and future roles (no deployment decision implied).', 'Developed through the SMR foundations micro-credential and expert lectures; awareness of concepts, no deployment decision implied.', 'Assessed through the micro-credential criteria and a short concept review, separate from current plant systems.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-09-01T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-09-08T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-09-15T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-09-15T11:00:00Z', 'sc-045', '2026-09-15T11:00:00Z'),
('scr-047', 'add', null, 'Add "Advanced fuel-cycle awareness"', 'إضافة «الوعي بدورة الوقود المتقدمة»', '{"name_en":"Advanced fuel-cycle awareness","name_ar":"الوعي بدورة الوقود المتقدمة","description_en":"Explains advanced fuel forms such as TRISO and HALEU, and what they change for handling, transport and supply. Part of Reactor theory and nuclear physics fundamentals (PF-01). Awareness only: no deployment decision is implied.","description_ar":"يشرح أشكال الوقود المتقدمة مثل TRISO وHALEU، وما تغيّره في المناولة والنقل والإمداد. جزء من نظرية المفاعل وأساسيات الفيزياء النووية (PF-01). للتوعية فقط: لا يعني ذلك أي قرار بالنشر.","area":"plant_systems","competency_id":"pf-01","fs_area":"advanced_reactor","key_level":2,"decay_class":"standard","owner_role":"advanced_reactors","source_label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","source_url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}'::jsonb, 'Awareness of next-generation reactor concepts is needed for the SMR delta and future roles (no deployment decision implied).', 'Developed through the SMR foundations micro-credential and expert lectures; awareness of concepts, no deployment decision implied.', 'Assessed through the micro-credential criteria and a short concept review, separate from current plant systems.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-09-01T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-09-08T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-09-15T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-09-15T11:00:00Z', 'sc-046', '2026-09-15T11:00:00Z'),
('scr-048', 'add', null, 'Add "Fusion awareness"', 'إضافة «الوعي بالاندماج النووي»', '{"name_en":"Fusion awareness","name_ar":"الوعي بالاندماج النووي","description_en":"Explains how fusion differs from fission, where the main research programmes stand and which plant skills would transfer. Part of Reactor theory and nuclear physics fundamentals (PF-01). Awareness only: no deployment decision is implied.","description_ar":"يشرح كيف يختلف الاندماج عن الانشطار، وأين تقف برامج البحث الرئيسية، وأي مهارات المحطة يمكن أن تنتقل إليه. جزء من نظرية المفاعل وأساسيات الفيزياء النووية (PF-01). للتوعية فقط: لا يعني ذلك أي قرار بالنشر.","area":"plant_systems","competency_id":"pf-01","fs_area":"advanced_reactor","key_level":1,"decay_class":"fast","owner_role":"advanced_reactors","source_label":"OECD-NEA NEST Framework and Plan 2035","source_url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf"}'::jsonb, 'Awareness of next-generation reactor concepts is needed for the SMR delta and future roles (no deployment decision implied).', 'Developed through the SMR foundations micro-credential and expert lectures; awareness of concepts, no deployment decision implied.', 'Assessed through the micro-credential criteria and a short concept review, separate from current plant systems.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-09-01T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-09-08T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-09-15T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-09-15T11:00:00Z', 'sc-047', '2026-09-15T11:00:00Z'),
('scr-049', 'add', null, 'Add "Microreactor and transportable unit concepts"', 'إضافة «مفاهيم المفاعلات الدقيقة والوحدات القابلة للنقل»', '{"name_en":"Microreactor and transportable unit concepts","name_ar":"مفاهيم المفاعلات الدقيقة والوحدات القابلة للنقل","description_en":"Describes microreactor concepts, factory-sealed cores and transport considerations, and the different operating model they imply. Part of APR-1400 integrated plant systems (PF-03). Awareness only: no deployment decision is implied.","description_ar":"يصف مفاهيم المفاعلات الدقيقة والقلوب المختومة في المصنع واعتبارات النقل، ونموذج التشغيل المختلف الذي تقتضيه. جزء من أنظمة محطة APR-1400 المتكاملة (PF-03). للتوعية فقط: لا يعني ذلك أي قرار بالنشر.","area":"plant_systems","competency_id":"pf-03","fs_area":"advanced_reactor","key_level":2,"decay_class":"standard","owner_role":"advanced_reactors","source_label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","source_url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}'::jsonb, 'Awareness of next-generation reactor concepts is needed for the SMR delta and future roles (no deployment decision implied).', 'Developed through the SMR foundations micro-credential and expert lectures; awareness of concepts, no deployment decision implied.', 'Assessed through the micro-credential criteria and a short concept review, separate from current plant systems.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-09-01T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-09-08T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-09-15T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-09-15T11:00:00Z', 'sc-048', '2026-09-15T11:00:00Z'),
('scr-050', 'add', null, 'Add "Advanced-reactor regulatory awareness"', 'إضافة «الوعي التنظيمي بالمفاعلات المتقدمة»', '{"name_en":"Advanced-reactor regulatory awareness","name_ar":"الوعي التنظيمي بالمفاعلات المتقدمة","description_en":"Explains how regulators internationally are adapting their approaches for new designs, without anticipating any regulatory decision. Part of Technical specifications and the licensing basis (NS-02). Awareness only: no deployment decision is implied.","description_ar":"يشرح كيف تكيّف الجهات الرقابية حول العالم مناهجها للتصاميم الجديدة، دون استباق أي قرار رقابي. جزء من المواصفات الفنية وأساس الترخيص (NS-02). للتوعية فقط: لا يعني ذلك أي قرار بالنشر.","area":"safety","competency_id":"ns-02","fs_area":"advanced_reactor","key_level":2,"decay_class":"standard","owner_role":"safety_licensing","source_label":"OECD-NEA NEST Framework and Plan 2035","source_url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf"}'::jsonb, 'Awareness of next-generation reactor concepts is needed for the SMR delta and future roles (no deployment decision implied).', 'Developed through the SMR foundations micro-credential and expert lectures; awareness of concepts, no deployment decision implied.', 'Assessed through the micro-credential criteria and a short concept review, separate from current plant systems.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'published', 'p-k-instructor', 'instructor', '2026-09-01T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":null,"at":"2026-09-08T10:00:00Z"},{"by":"p-chco","role":"hr_director","decision":"approve","note":null,"at":"2026-09-15T11:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', 'p-chco', '2026-09-15T11:00:00Z', 'sc-049', '2026-09-15T11:00:00Z'),
('scr-051', 'rename', 'sk-fs-ai-prompt', 'Rename "Prompt and agent literacy" to "Prompting and AI-agent oversight"', 'إعادة تسمية «الإلمام بصياغة الأوامر والوكلاء الذكيين» إلى «صياغة الأوامر والإشراف على وكلاء الذكاء الاصطناعي»', '{"name_en":"Prompting and AI-agent oversight","name_ar":"صياغة الأوامر والإشراف على وكلاء الذكاء الاصطناعي"}'::jsonb, 'Learners read "literacy" as awareness only; the skill is about directing and overseeing agents in the approved tools.', 'Unchanged: the AI fluency rungs and the governed sandbox drills on agents.', 'Unchanged: the agent drills and the adaptive AI-literacy items mapped to this skill.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'submitted', 'p-k-instructor', 'instructor', '2026-09-30T08:00:00Z', '[]'::jsonb, null, null, null, null, null, '2026-09-30T08:00:00Z'),
('scr-052', 'split', 'sk-fs-ai-dataeng', 'Split "Data engineering basics" into 2 skills', 'تقسيم «أساسيات هندسة البيانات» إلى 2 مهارات', '{"parts":[{"name_en":"Data pipeline basics","name_ar":"أساسيات خطوط البيانات","description_en":"Moves plant and work data between systems with checks, logs and owners for each step.","description_ar":"ينقل بيانات المحطة والعمل بين الأنظمة مع فحوص وسجلات ومالك لكل خطوة."},{"name_en":"Data modelling basics","name_ar":"أساسيات نمذجة البيانات","description_en":"Structures plant and work data into clear entities, keys and definitions others can reuse.","description_ar":"ينظّم بيانات المحطة والعمل في كيانات ومفاتيح وتعريفات واضحة يمكن للآخرين إعادة استخدامها."}]}'::jsonb, 'Pipelines and modelling are taught in different courses and assessed by different tasks; one skill hides which one a person has.', 'Pipelines through the plant-data course labs; modelling through the data modelling workshop with the engineering data team.', 'Pipelines: a performance task on a drifting channel; modelling: a reviewed model of a work-order dataset.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'first_approved', 'p-sme-reviewer', 'employee', '2026-10-01T08:00:00Z', '[{"by":"p-training-mgr","role":"training_manager","decision":"approve","note":"Two development routes and two assessments: meets the inclusion rule.","at":"2026-10-05T10:00:00Z"}]'::jsonb, 'p-training-mgr', 'approve', null, null, null, '2026-10-05T10:00:00Z'),
('scr-053', 'retire', 'sk-fs-dp-paperlog', 'Retire "Paper log-sheet rounds"', 'إيقاف «الجولات بسجلات ورقية»', '{"replaced_by":"sk-fs-dp-rounds"}'::jsonb, 'Digital operator rounds replace paper log sheets in the rollout plan; keep the skill readable but stop developing it.', 'No new development: the digital rounds course covers the replacement skill.', 'No new assessment: digital rounds are observed on the new tablets.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'first_approved', 'p-training-mgr', 'training_manager', '2026-10-02T08:00:00Z', '[{"by":"p-chco","role":"hr_director","decision":"approve","note":"Agreed with the rollout plan; the replacement is live.","at":"2026-10-06T10:00:00Z"}]'::jsonb, 'p-chco', 'approve', null, null, null, '2026-10-06T10:00:00Z'),
('scr-054', 'relevel', 'sk-fs-cy-report', 'Re-level "Reporting a suspected cyber incident" to key level 2', 'إعادة تحديد مستوى «الإبلاغ عن حادث سيبراني مشتبه به» إلى المستوى المحوري 2', '{"key_level":2,"level_essence_en":"Practitioner: reports a suspected cyber incident through the right channel without delay, preserves what was seen and briefs the next shift.","level_essence_ar":"ممارس: يبلّغ عن الحادث السيبراني المشتبه به عبر القناة الصحيحة دون تأخير، ويحفظ ما شوهد ويطلع المناوبة التالية."}'::jsonb, 'Reporting is expected from every shift supervisor at practitioner level, not awareness.', 'The reporting drill in the yearly cyber hygiene refresher, run by shift.', 'Observed during the shift reporting drill against the practitioner essence.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'submitted', 'p-head-sq', 'manager', '2026-10-05T08:00:00Z', '[]'::jsonb, null, null, null, null, null, '2026-10-05T08:00:00Z'),
('scr-055', 'add', null, 'Add "AI risk awareness for safety-related work"', 'إضافة «الوعي بمخاطر الذكاء الاصطناعي في الأعمال المتصلة بالسلامة»', '{"name_en":"AI risk awareness for safety-related work","name_ar":"الوعي بمخاطر الذكاء الاصطناعي في الأعمال المتصلة بالسلامة","description_en":"Recognises where an AI output could affect safety-related work and stops to confirm with the controlled source.","description_ar":"يدرك المواضع التي قد يؤثر فيها مخرَج الذكاء الاصطناعي في الأعمال المتصلة بالسلامة ويتوقف للتأكد من المصدر الخاضع للرقابة.","area":"digital","competency_id":"da-02","fs_area":"ai_data","key_level":1,"decay_class":"fast","owner_role":"digital_ai_governance","source_label":"European Commission · EU AI Act Article 4 AI-literacy repository","source_url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices"}'::jsonb, 'Operators meet AI summaries in turnover notes; awareness of where they touch safety-related work is not covered by everyday tool use.', 'The AI-era HU tool cards and the turnover drill, with a safety-culture briefing by shift.', 'Situation questions in the AI-literacy bank tagged to this skill, separate from tool use and verification.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'submitted', 'p-k-ro', 'licensed_operator', '2026-10-07T08:00:00Z', '[]'::jsonb, null, null, null, null, null, '2026-10-07T08:00:00Z'),
('scr-056', 'add', null, 'Add "Spreadsheet skills"', 'إضافة «مهارات جداول البيانات»', '{"name_en":"Spreadsheet skills","name_ar":"مهارات جداول البيانات","area":"digital","competency_id":"da-01","key_level":2,"source_label":"European Commission JRC · DigComp, the digital competence framework for citizens","source_url":"https://joint-research-centre.ec.europa.eu/scientific-activities-z/education-and-training/digital-transformation-education/digital-competence-framework-citizens-digcomp_en"}'::jsonb, 'Procurement uses spreadsheets every day and wants the skill in development plans.', 'Office tools training from the corporate catalogue.', 'A practical spreadsheet exercise set by the trainer.', '[{"key":"skill","ok":true},{"key":"names","ok":true},{"key":"distinct_name","ok":true},{"key":"development","ok":true},{"key":"assessment","ok":true},{"key":"source","ok":true},{"key":"replacement","ok":true},{"key":"level","ok":true}]'::jsonb, 'first_rejected', 'p-nse', 'employee', '2026-10-08T08:00:00Z', '[{"by":"p-k-admin","role":"admin","decision":"reject","note":"Too generic for the nuclear catalogue: covered by Technological literacy (FS-TR-06) and Data engineering basics.","at":"2026-10-09T10:00:00Z"}]'::jsonb, 'p-k-admin', 'reject', null, null, null, '2026-10-09T10:00:00Z')
